enum Mode {
  DESIGN
  GAME
}

enum Color {
  WHITE
  BLACK
}

class TileO {}

class Game {
  + mode : Mode
  + spareConnectionPieces : int = 32
  + numberOfActionCards : int = 32
}

class Connection {}

class Die {}

class Deck {}

abstract class Tile {
  + color : Color
}

class WinTile extends Tile {}

class ActionTile extends Tile {
  + turnsUntilActive : int
}

class NormalTile extends Tile {}

abstract class ActionCard {
  + instructions : string
}

class RollDieActionCard extends ActionCard {}

class ConnectTilesActionCard extends ActionCard {}

class RemoveConnectionActionCard extends ActionCard {}

class TeleportActionCard extends ActionCard {}

class LoseTurnActionCard extends ActionCard {}

class Player {
  + color : Color
}

TileO "1" *-- "1" Game
Game "1" *-- "*" Tile
Game "1" *-- "*" Connection
Game "1" *-- "1" Die
Game "1" *-- "1" Deck
Game "1" --> "0..1" Player : currentPlayer
Game "1" *-- "2..4" Player
Game "1" --> "0..1" WinTile : hiddenTile
Tile "1" -- "0..4" Connection : connects to
Player "1" --> "1" Tile : currentTile
Player "1" --> "1" Tile : startingTile
Deck "1" *-- "0..32" ActionCard
ActionTile "1" --> "0..1" ActionCard : triggers

@enduml

